import { PlaneGeometry, MeshBasicNodeMaterial, Group, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.cleanup = () => {};
  group.userData.handlers = {};

  // --- Image plane ---
  const aspect = 512 / 320; // from source rect
  const width = 4.0;
  const height = width / aspect;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface fallback
    transparent: false,
    side: ctx.THREE.DoubleSide,
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = -0.01; // slight offset behind text
  group.add(plane);

  // Load texture (async)
  const loadTex = ctx.textureLoader.loadTexture(config.imageUrl);
  loadTex.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text "Collection" ---
  const textOpts = {
    fontSize: 96,
    color: '#e8ecf2', // paper
    align: 'center',
    maxWidthPx: width * 100, // approx scene-unit to pixel scale
  };
  const textObj = ctx.fontAtlas.createText('Collection', textOpts);
  textObj.position.set(0, 0, 0.01);
  group.add(textObj);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    loadTex.then((tex) => tex.dispose()).catch(() => {});
    group.remove(textObj);
    // No GSAP timelines to kill
  };

  return group;
}
